('bmlt-laboratory-informatics-lims-reporting-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',3800,$json${"question":"A Laboratory Information Management System (LIMS) is primarily used to:","translation":"","options":["Manage laboratory samples, workflows and results","Sterilize instruments","Perform blood collection","Replace all laboratory staff"],"correctIndex":0,"explanation":"A LIMS supports sample tracking, workflow management, data handling and reporting.","explanationNe":"LIMS ले नमुना tracking, workflow, data management र reporting मा सहयोग गर्छ।","topic":"LIMS"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',3801,$json${"question":"The unique identifier assigned to a laboratory specimen is important because it:","translation":"","options":["Links the specimen to the correct patient and request","Indicates the patient's diagnosis","Replaces quality control","Determines the test result"],"correctIndex":0,"explanation":"A unique identifier supports traceability and reduces specimen mix-ups.","explanationNe":"Unique identifier ले specimen लाई सही patient र request सँग जोड्छ।","topic":"Specimen identification"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3802,$json${"question":"Barcode scanning during specimen reception helps to:","translation":"","options":["Reduce manual identification and transcription errors","Increase haemolysis","Replace specimen acceptance criteria","Validate every analytical result automatically"],"correctIndex":0,"explanation":"Barcode systems improve identification accuracy and traceability when used correctly.","explanationNe":"Barcode scanning ले पहिचान र data entry सम्बन्धी त्रुटि घटाउँछ।","topic":"Barcode systems"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',3803,$json${"question":"An audit trail in a laboratory information system records:","translation":"","options":["Who changed data, what changed and when","Only the patient's diagnosis","Only reagent expiry dates","Only instrument temperature"],"correctIndex":0,"explanation":"An audit trail documents changes and supports accountability and traceability.","explanationNe":"Audit trail ले कसले, के र कहिले परिवर्तन गर्‍यो भन्ने अभिलेख राख्छ।","topic":"Audit trail"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',3804,$json${"question":"Role-based access control is designed to:","translation":"","options":["Limit system functions according to authorized user roles","Allow every user to edit every result","Remove passwords","Share patient data publicly"],"correctIndex":0,"explanation":"Role-based permissions restrict access to functions and information according to assigned duties.","explanationNe":"Role अनुसार permission दिएर अनधिकृत access रोकिन्छ।","topic":"Access control"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',3805,$json${"question":"A critical laboratory result should be:","translation":"","options":["Communicated promptly to an authorized clinician and documented","Held until the next routine report","Sent to social media","Changed to a normal value"],"correctIndex":0,"explanation":"Critical values require timely communication, read-back where required and documentation.","explanationNe":"Critical result तुरुन्त सम्बन्धित clinician लाई जानकारी दिई अभिलेख राख्नुपर्छ।","topic":"Critical result communication"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',3806,$json${"question":"The purpose of delta checking is to:","translation":"","options":["Compare a patient's current result with previous results for significant change","Compare two laboratories' logos","Check reagent colour only","Calculate staff attendance"],"correctIndex":0,"explanation":"Delta checks identify unexpected changes that may reflect clinical change or error.","explanationNe":"Delta check ले अघिल्लो र हालको result बीचको असामान्य परिवर्तन पत्ता लगाउँछ।","topic":"Delta check"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',3807,$json${"question":"A reference interval generally describes:","translation":"","options":["The distribution of results in a defined reference population","The guaranteed range for every diseased patient","The instrument's electrical voltage","The minimum sample volume"],"correctIndex":0,"explanation":"Reference intervals are derived from a defined population and must be interpreted in clinical context.","explanationNe":"Reference interval निश्चित reference population का result को दायरा हो; clinical context आवश्यक हुन्छ।","topic":"Reference intervals"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',3808,$json${"question":"A laboratory's analytical measuring range refers to:","translation":"","options":["The range over which an assay can measure directly without dilution or concentration","The age range of patients","The period a reagent can be stored","The number of staff on duty"],"correctIndex":0,"explanation":"The analytical measuring range defines concentrations that can be measured directly under stated conditions.","explanationNe":"Analytical measuring range भनेको assay ले dilution नगरी सीधै मापन गर्न सक्ने दायरा हो।","topic":"AMR"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',3809,$json${"question":"A result outside the analytical measurement range should generally be:","translation":"","options":["Handled according to validated dilution or repeat procedures","Reported as an exact value without qualification","Deleted automatically","Converted to zero"],"correctIndex":0,"explanation":"Out-of-range results require validated dilution, repeat testing or an appropriate reporting comment.","explanationNe":"दायराभन्दा बाहिरको result लाई validated dilution वा repeat procedure अनुसार जाँच्नुपर्छ।","topic":"Out-of-range results"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',3810,$json${"question":"Autoverification in a laboratory system means:","translation":"","options":["Automatic release of results meeting predefined validated rules","Automatic diagnosis of every disease","Automatic collection of specimens","Automatic replacement of QC"],"correctIndex":0,"explanation":"Autoverification applies predefined rules and should include safeguards and monitoring.","explanationNe":"Autoverification ले निर्धारित rule पूरा भएका result स्वतः release गर्छ; monitoring आवश्यक हुन्छ।","topic":"Autoverification"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',3811,$json${"question":"A result should be withheld from autoverification when:","translation":"","options":["A defined rule or instrument flag requires manual review","The patient has a common surname","The sample was collected in the morning","The result is within range"],"correctIndex":0,"explanation":"Flags, critical limits, QC failures and other rule violations should trigger review.","explanationNe":"Instrument flag, critical limit वा QC समस्या भए manual review गर्नुपर्छ।","topic":"Autoverification rules"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',3812,$json${"question":"A laboratory report should include:","translation":"","options":["Patient identifiers, specimen details, test result, units and relevant reference information","Only the numerical result without units","The technologist's personal opinion","Unverified diagnoses"],"correctIndex":0,"explanation":"Clear reports need traceable identifiers, result units and appropriate interpretive information.","explanationNe":"Report मा patient पहिचान, specimen विवरण, result, unit र आवश्यक reference information हुनुपर्छ।","topic":"Report content"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',3813,$json${"question":"The SI unit for concentration should be reported:","translation":"","options":["Consistently according to the laboratory's approved method and reporting policy","Randomly selected for each patient","Without any unit","Only in handwritten notes"],"correctIndex":0,"explanation":"Consistent units prevent interpretation and conversion errors.","explanationNe":"एकरूप unit ले result बुझ्न र तुलना गर्न सजिलो बनाउँछ।","topic":"Units"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',3814,$json${"question":"A transcription error is best described as:","translation":"","options":["Incorrect transfer of information from one record or system to another","A biological variation","A normal analytical fluctuation","A type of blood cell"],"correctIndex":0,"explanation":"Transcription errors occur when data are copied or entered incorrectly.","explanationNe":"एउटा record बाट अर्कोमा data सार्दा गलत लेखिनु transcription error हो।","topic":"Data integrity"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',3815,$json${"question":"The principle of least privilege means users should receive:","translation":"","options":["Only the access needed to perform their assigned duties","Administrator rights by default","Access to all patient records","No access logging"],"correctIndex":0,"explanation":"Least privilege limits access to the minimum necessary for the user's role.","explanationNe":"प्रत्येक user लाई कामका लागि चाहिने न्यूनतम access मात्र दिनुपर्छ।","topic":"Cybersecurity"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',3816,$json${"question":"A scheduled system backup is intended to:","translation":"","options":["Enable recovery of data after loss or system failure","Improve analytical sensitivity","Sterilize the server","Replace daily QC"],"correctIndex":0,"explanation":"Backups support recovery after accidental deletion, corruption or system failure.","explanationNe":"Backup ले data हराए वा system बिग्रिएमा पुनः प्राप्त गर्न मद्दत गर्छ।","topic":"Data backup"}$json$::jsonb,true),
