('bmlt-laboratory-informatics-lims-reporting-mock-004','BMLT','BMLT NHPC Licensing','mock','free',3903,$json${"question":"A clinician phones asking for a critical potassium result. What should the staff member do?","translation":"","options":["Verify the caller's authorization, communicate the result and document the call","Give results to anyone who asks","Delay until a printed report is ready","Send the result to an open group chat"],"correctIndex":0,"explanation":"Critical results must be communicated securely to an authorized recipient and documented.","explanationNe":"Caller अधिकृत हो कि होइन पुष्टि गरी critical result जानकारी र अभिलेख गर्नुपर्छ।","topic":"Critical communication"}$json$::jsonb,true),
