('bmlt-laboratory-informatics-lims-reporting-mock-017','BMLT','BMLT NHPC Licensing','mock','free',3916,$json${"question":"A high percentage of reports exceed the laboratory's TAT target. What is a useful first step?","translation":"","options":["Analyze delays by workflow stage and test category","Increase all reference intervals","Stop recording receipt times","Remove the TAT target"],"correctIndex":0,"explanation":"Stratifying delays helps identify where corrective action is needed.","explanationNe":"कुन चरणमा ढिलाइ छ भनेर छुट्याएर कारण पहिचान गर्नुपर्छ।","topic":"KPI improvement"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mock-018','BMLT','BMLT NHPC Licensing','mock','free',3917,$json${"question":"A laboratory introduces a new LIS interface to an analyzer. Before go-live, it should:","translation":"","options":["Verify data mapping, units, flags and result transmission using test cases","Assume the interface is correct","Test only the login screen","Disable audit logging"],"correctIndex":0,"explanation":"Interface verification should cover accurate transmission and interpretation of patient and QC data.","explanationNe":"नयाँ interface सुरु गर्नुअघि data, unit, flag र result transmission परीक्षण गर्नुपर्छ।","topic":"Interface validation"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mock-019','BMLT','BMLT NHPC Licensing','mock','free',3918,$json${"question":"A patient result appears under the wrong test name after an interface update. What is the safest response?","translation":"","options":["Stop affected reporting, investigate mapping and assess previously transmitted results","Continue reporting and correct later","Change the patient's diagnosis","Delete the analyzer"],"correctIndex":0,"explanation":"Incorrect mapping can cause clinically dangerous reporting errors and requires containment and impact review.","explanationNe":"गलत test mapping ले जोखिम निम्त्याउँछ; reporting रोक्दै असर परेको result समेत जाँच्नुपर्छ।","topic":"Interface error"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mock-020','BMLT','BMLT NHPC Licensing','mock','free',3919,$json${"question":"A system backup has been scheduled but has never been tested. What is missing?","translation":"","options":["A documented restore test to confirm recoverability","A new barcode font","A second reference interval","An additional centrifuge"],"correctIndex":0,"explanation":"Backup success is not assured until restoration has been tested and documented.","explanationNe":"Backup बाट data फर्काउन सकिन्छ कि भनेर restore test गर्नुपर्छ।","topic":"Backup recovery"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mock-021','BMLT','BMLT NHPC Licensing','mock','free',3920,$json${"question":"A laboratory report is automatically released despite a critical-value rule. What should be reviewed?","translation":"","options":["Autoverification rule configuration and validation","The colour of the report logo","Staff uniforms","Patient waiting-room seating"],"correctIndex":0,"explanation":"Critical-value rules must be correctly configured, validated and monitored to prevent unsafe release.","explanationNe":"Critical value सम्बन्धी autoverification rule सही configure र validate भएको छ कि जाँच्नुपर्छ।","topic":"Autoverification"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mock-022','BMLT','BMLT NHPC Licensing','mock','free',3921,$json${"question":"An external clinician requests a patient's result but cannot provide authorization. What should the laboratory do?","translation":"","options":["Follow identity, consent and authorized disclosure policy before release","Send the result immediately","Post the result publicly","Give access to the full LIS"],"correctIndex":0,"explanation":"Results must be disclosed only after appropriate authorization and identity checks.","explanationNe":"उचित authorization र पहिचान पुष्टि भएपछि मात्र result दिनुपर्छ।","topic":"Data privacy"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mock-023','BMLT','BMLT NHPC Licensing','mock','free',3922,$json${"question":"A staff member shares their LIS password with a colleague to save time. What is the main risk?","translation":"","options":["Loss of individual accountability and unauthorized access","Improved audit quality","Better analytical precision","Reduced specimen volume"],"correctIndex":0,"explanation":"Shared credentials undermine access control and make user actions difficult to attribute.","explanationNe":"Password share गर्दा कसले के गर्‍यो भन्ने accountability हराउँछ र unauthorized access हुन सक्छ।","topic":"Password security"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mock-024','BMLT','BMLT NHPC Licensing','mock','free',3923,$json${"question":"A laboratory changes its reference interval after adopting a new method. What should be done?","translation":"","options":["Verify or establish appropriate intervals and update the LIS and report templates","Keep the old interval without assessment","Change only the analyzer screen","Remove units from reports"],"correctIndex":0,"explanation":"Reference intervals should be appropriate to the method and population and consistently implemented.","explanationNe":"नयाँ method अनुसार reference interval जाँचेर LIS र report मा अद्यावधिक गर्नुपर्छ।","topic":"Reference interval verification"}$json$::jsonb,true),
('bmlt-laboratory-informatics-lims-reporting-mock-025','BMLT','BMLT NHPC Licensing','mock','free',3924,$json${"question":"An electronic result is approved by a user who is not authorized for that test section. What is the correct action?","translation":"","options":["Escalate, correct the authorization issue and review affected reports","Accept it because it is electronic","Delete the user's account without investigation","Ignore the approval record"],"correctIndex":0,"explanation":"Result authorization must follow documented competency and role permissions.","explanationNe":"Result approval सम्बन्धित व्यक्तिको अधिकार र competency अनुसार हुनुपर्छ।","topic":"Authorization"}$json$::jsonb,true)
